Q: Removing Transforms manually from SVG A: <p>Provided you have nice and clean coordinate object/array structure the math is indeed quite trivial:</p>
<p><div class="snippet" data-lang="js" data-hide="true" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code snippet-currently-hidden">
<pre class="snippet-code-js lang-js prettyprint-override"><code>/** 
* consolidated matrix from tranform functions
* translate(15 10) scale(0.9) rotate(45 50 50) skewX(10) translate(-15 5)
*/
let mtx = [0.636396,0.636396,-0.524182,0.74861,47.833146,-14.442505];

let rect= [
  {x:25, y:25},
  {x:75, y:25},
  {x:75, y:75},
  {x:25, y:75},
];


let polyTranformed = rect.map(pt=&gt;transformPoint(pt, mtx))
let polyAtt = polyTranformed.map(pt=&gt;{return `${pt.x} ${pt.y}`}).join(' ');
polyEl.setAttribute('points', polyAtt )


// transform point by 2d matrix
function transformPoint (pt, matrix) {
  let a, b, c, d, e, f;
  if(Array.isArray(matrix)){
    [a, b, c, d, e, f] = matrix
  }else{
    ({ a, b, c, d, e, f } = matrix);
  }
  let { x, y } = pt;
  return { x: a * x + c * y + e, y: b * x + d * y + f };
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;h3&gt;SVG transform merged to matrix&lt;/h3&gt;
&lt;svg id="svg1" viewBox="0 0 100 100"&gt;
  &lt;g transform="matrix(0.636396,0.636396,-0.524182,0.74861,47.833146,-14.442505)"&gt;
    &lt;path id="path1" d="M 25 25 h 50 v 50 h-50 z"/&gt;
  &lt;/g&gt;
&lt;/svg&gt;


&lt;h3&gt;Poly transform applied&lt;/h3&gt;
&lt;svg id="svgP" viewBox="0 0 100 100"&gt;
    &lt;polygon id="polyEl" points=""/&gt;
&lt;/svg&gt;</code></pre>
</div>
</div>
</p>
<h3>Requirements for transformed coordinate calculations</h3>
<ul>
<li>a path data parser and normalizer: if you're also dealing with external highly optimized SVG data you need to unravel relative, shorthand or highly minified notations (especially <code>A</code> elliptic arc commands). A simplistic regex parser won't work.</li>
<li>maybe also a shape to path conversion in case you also work with primitives like <code>&lt;circle&gt;</code>, <code>&lt;ellipse&gt;</code>, <code>&lt;rect&gt;</code></li>
<li>a helper that combines all applied transformations into a consolidated transform matrix – we also have to respect <code>transform-origin</code> definitions</li>
<li>a logic to remove transform properties in time (not prematurely)</li>
</ul>
<h3>SVG vs CSS transforms</h3>
<p>Both SVG and CSS include a mostly compatible set of transform functions to provide a more intuitive/readable abstraction of affine 2D transformation matrices.<br />
However, we have »false friends« so subtle differences that often cause confusions – for instance:</p>
<ul>
<li>SVG's <code>rotate()</code> function allows a 3rd parameter for the rotation origin (actually pretty handy) – CSS doesn't</li>
<li>CSS transforms usually require explicit units such as <code>px</code> or <code>deg</code> (albeit many browsers have implemented some tolerance)</li>
</ul>
<h3>Client side JS Example:</h3>
<p>As long as you have methods for the aforementioned requirements it doesn't matter whether you do it server-side, in a headless environment or client-side. However, a client side JS approach can take advantage of native API methods especially for matrix consolidation.</p>
<p>The following example parses the path data via SVG2 method <code>getPathData()</code> with the normalize parameter – converting all commands to absolute, replacing shorthand commands to their verbose longhand equivalents and also converting <code>A</code> eliptic arc commands to cubic Bézier approximations (as well as quadratic commands to cubic).</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>console.clear();
let matrix = getElementTransform(path0, svg0);

/**
 * parse pathData to normalized 
 * absolute and longhand commands
 */
let pathData = path0.getPathData({
  normalize: true
})

// calculate transforms
let pathDataTransformed = transformPathData(pathData, matrix);

// apply pathdata
let d = pathDataTransformed.map(com =&gt; {
  return [com.type, com.values]
}).flat().join(' ')

/**
 * you could also use setPathData() method
 * but it's not too impressive as 
 * it simply stringifies pathData to a d attribute
 */
//path2.setPathData(pathDataTransformed)
path2.setAttribute('d', d)

// show pathData output
svgOut.value = d

function transformPathData(pathData, matrix) {
  let pathDataTransformed = [];

  pathData.forEach(com =&gt; {
    let {
      type,
      values
    } = com;

    // Z commands don't have values
    if (values.length) {
      let valuesTransformed = [];

      // loop x/y coordinate pairs
      for (let i = 1, l = values.length; i &lt; l; i += 2) {
        let pt = {
          x: values[i - 1],
          y: values[i]
        }
        let ptTransformed = transformPoint(pt, matrix)
        valuesTransformed.push(ptTransformed.x, ptTransformed.y)
      }
      pathDataTransformed.push({
        type,
        values: valuesTransformed
      })

    } else {
      pathDataTransformed.push(com)
    }
  })

  return pathDataTransformed;
}


// transform point by 2d matrix
function transformPoint(pt, matrix) {
  let {
    a,
    b,
    c,
    d,
    e,
    f
  } = matrix
  return {
    x: a * pt.x + c * pt.y + e,
    y: b * pt.x + d * pt.y + f
  };
}

/**
 * get element's transform matrix 
 * via browser APIs
 */
function getElementTransform(el, parent) {
  return parent.getScreenCTM().inverse().multiply(el.getScreenCTM());
}</code></pre>
